CREATE OR REPLACE PACKAGE BODY billing_api AS
  PROCEDURE pay(p_bill_id IN NUMBER, p_amount IN NUMBER) IS
    l_bill_amount NUMBER;
    l_total_paid  NUMBER;
  BEGIN
    INSERT INTO bill_payments (bill_id, amount)
    VALUES (p_bill_id, p_amount);

    SELECT amount INTO l_bill_amount
    FROM bills
    WHERE bill_id = p_bill_id;

    SELECT SUM(amount) INTO l_total_paid
    FROM bill_payments
    WHERE bill_id = p_bill_id;

    UPDATE bills
    SET status = CASE
                   WHEN l_total_paid >= l_bill_amount THEN 'PAID'
                   ELSE 'PARTIAL'
                 END
    WHERE bill_id = p_bill_id;
  END pay;
END billing_api;
/
